package com.itu.gestionRH.entity.organization;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="CRENEAU_TRAVAIL") public class CreneauTravail { @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="creneauGen") @SequenceGenerator(name="creneauGen",sequenceName="SEQ_CRENEAU_TRAVAIL",allocationSize=1) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="PLANNING_ID",nullable=false) private PlanningTravail planning; @Column(name="DATE_DEBUT") private LocalDateTime dateDebut; @Column(name="DATE_FIN") private LocalDateTime dateFin; @Column(name="TYPE_CRENEAU",length=20) private String typeCreneau; @Column(length=200) private String libelle; @Column(nullable=false,length=15) private String statut="PLANIFIE"; @Column(name="STATUT_EMPLOYE",length=20) private String statutEmploye="NON_COMMENCE"; @Column(name="COMMENTAIRE_EMPLOYE",length=500) private String commentaireEmploye; @Column(name="DATE_DECLARATION") private LocalDateTime dateDeclaration; @Column(name="STATUT_VALIDATION",length=20) private String statutValidation="EN_ATTENTE"; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="VALIDATEUR_ID") private Employe validateur; @Column(name="DATE_VALIDATION") private LocalDateTime dateValidation; public Long getId(){return id;} public PlanningTravail getPlanning(){return planning;} public void setPlanning(PlanningTravail v){planning=v;} public LocalDateTime getDateDebut(){return dateDebut;} public void setDateDebut(LocalDateTime v){dateDebut=v;} public LocalDateTime getDateFin(){return dateFin;} public void setDateFin(LocalDateTime v){dateFin=v;} public String getTypeCreneau(){return typeCreneau;} public void setTypeCreneau(String v){typeCreneau=v;} public String getLibelle(){return libelle;} public void setLibelle(String v){libelle=v;} public String getStatut(){return statut;} public void setStatut(String v){statut=v;} public String getStatutEmploye(){return statutEmploye;} public void setStatutEmploye(String v){statutEmploye=v;} public String getCommentaireEmploye(){return commentaireEmploye;} public void setCommentaireEmploye(String v){commentaireEmploye=v;} public LocalDateTime getDateDeclaration(){return dateDeclaration;} public void setDateDeclaration(LocalDateTime v){dateDeclaration=v;} public String getStatutValidation(){return statutValidation;} public void setStatutValidation(String v){statutValidation=v;} public Employe getValidateur(){return validateur;} public void setValidateur(Employe v){validateur=v;} public LocalDateTime getDateValidation(){return dateValidation;} public void setDateValidation(LocalDateTime v){dateValidation=v;} }
